def plan(tasks):
    visiting = set()
    finished = set()
    result = []
    def visit(name):
        if name not in tasks or name in visiting:
            return False
        if name in finished:
            return True
        visiting.add(name)
        for before in sorted(tasks[name]):
            if not visit(before):
                return False
        visiting.remove(name)
        finished.add(name)
        result.append(name)
        return True
    for name in sorted(tasks):
        if not visit(name):
            return None
    return result

